-- insert-jerez-centers.sql
-- Inserta los 37 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Jerez de la Frontera investigados y humanizados en este sprint.
-- Fuente primaria: "Centros de primer ciclo de educacion infantil en Andalucia, con
-- alumnado matriculado" (Junta de Andalucia, Consejeria de Desarrollo Educativo y
-- Formacion Profesional, portal de datos abiertos), filtrado por D_MUNICIPIO='Jerez de la Frontera'.
-- Complementado con: (a) el Portal de Escolarizacion 0-3 anos de la Junta de Andalucia
-- (horario homogeneo de la red publica autonomica) y (b) webs oficiales propias de un
-- subconjunto de centros privados para confirmar servicios concretos. Ver
-- docs/data-sources-jerez.md y data/enrichment/jerez-centers.json.
--
-- Ambito: unicamente el termino municipal de Jerez de la Frontera (D_MUNICIPIO='Jerez de la
-- Frontera' en la fuente oficial, valor exacto), incluyendo las pedanias de Guadalcacin,
-- Mesas de Asta, La Barca de la Florida y Torrecera. Se excluye explicitamente el resto de
-- la provincia de Cadiz (Cadiz capital, El Puerto de Santa Maria, Sanlucar de Barrameda,
-- Chiclana de la Frontera, Arcos de la Frontera, Rota, Puerto Real, etc.).
--
-- Ownership: 'publico' se ha usado unicamente para las 6 escuelas infantiles de la red
-- genuina de titularidad de la Junta de Andalucia (confirmadas por email institucional
-- @juntadeandalucia.es en la fuente oficial: Virgen del Valle, Santa Maria, San Carlos,
-- Rocinante, Primavera, El Paje). Los 31 centros privados adheridos o no al Programa de
-- Ayuda a las Familias de la Junta de Andalucia llevan ownership='privado', nunca
-- 'concertado': Andalucia no tiene concierto educativo formal para el primer ciclo de
-- infantil (0-3 anos). Un centro (Luna de Caramelo) se autodescribe engañosamente como
-- "guarderia publica" en su propia web pero figura como Privado/adherido en la fuente
-- oficial -> se mantiene ownership='privado' siguiendo la fuente oficial. Ver
-- docs/jerez-quality-report.md, seccion 1.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS hasta
-- cambiarlos a 'published' manualmente tras auditoria, igual que en el resto de zonas ya
-- integradas: Madrid, Barcelona, Valencia, Zaragoza, Murcia, Sevilla, Palma, Malaga,
-- Alicante, Las Palmas, Cordoba y Granada.
-- No toca ningun centro de ninguna de esas ciudades.
-- No borra ni modifica filas existentes (upsert por slug: si un slug ya existe se
-- actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "jerez-de-la-frontera" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('jerez-de-la-frontera', 'Jerez de la Frontera', 'Cádiz', 'Andalucía')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
